def build():
    out = []
    for code in ORDER:
        vals = RAW.get(code)
        if not vals:
            out.append({"code": code, "_error": "no_data"})
            continue
        rec = {"code": code}
        n = len(vals)
        rec["em_today"] = vals[-1][1]
        if n >= 5:
            rec["em_5d"] = sum(v for _, v in vals[-5:])
        if n >= 10:
            rec["em_10d"] = sum(v for _, v in vals[-10:])
        if n >= 20:
            rec["em_20d"] = sum(v for _, v in vals[-20:])
        out.append(rec)
    return out


